   6 /**
   7  * Saves a project to Firestore. If the project has an ID, it updates it.
   8  * Otherwise, it creates a new document.
   9  * @param projectData The project data to save.
  10  * @returns The saved project data with a confirmed ID and updated timestamp.
  11  */
  12 export async function saveProject(projectData: ProjectProperties): Promise<ProjectProperties> {
  13   const collection = adminDb.collection('projects');
  14   const docRef = projectData.id ? collection.doc(projectData.id) : collection.doc();
  15   
  16   const dataToSave = {
  17     ...projectData,
  18     id: docRef.id,
  19     meta: {
  20       ...projectData.meta,
  21       updated: new Date().toISOString(),
  22     }
  23   };
  24 
  25   await docRef.set(dataToSave, { merge: true });
  26   return dataToSave;
  27 }
  28 
  29 /**
  30  * Fetches all projects for a given user.
  31  * @param userId The ID of the user whose projects to fetch.
  32  * @returns An array of project properties.
  33  */
  34 export async function getProjects(userId: string): Promise<ProjectProperties[]> {
  35   const snapshot = await adminDb.collection('projects')
  36     .where('meta.author', '==', userId)
  37     .orderBy('meta.updated', 'desc')
  38     .get();
  39   
  40   if (snapshot.empty) {
  41     return [];
  42   }
  43 
  44   return snapshot.docs.map(doc => doc.data() as ProjectProperties);
  45 }
  46 
  47 /**
  48  * Fetches a single project by its ID.
  49  * @param projectId The ID of the project to fetch.
  50  * @returns The project properties or null if not found.
  51  */
  52 export async function getProject(projectId: string): Promise<ProjectProperties | null> {
  53   const doc = await adminDb.collection('projects').doc(projectId).get();
  54   if (!doc.exists) {
  55     return null;
  56   }
  57   return doc.data() as ProjectProperties;
  58 }
  59 
  60 /**
  61  * Deletes a project from Firestore.
  62  * @param projectId The ID of the project to delete.
  63  */
  64 export async function deleteProject(projectId: string): Promise<void> {
  65   await adminDb.collection('projects').doc(projectId).delete();
  66 }
