  11 import { ai } from '@/ai/genkit';
  12 import { GenerateTextInputSchema, GenerateTextOutputSchema, type GenerateTextInput, type GenerateTextOutput } from '@/ai/schemas';
  13 import { RECOMMENDED_TEMPERATURES } from '@/ai/utils/json-output-validator';
  14 
  15 // Note: This flow now needs to be called with a user-specific AI instance.
  16 // The API route will handle creating this instance based on the user's stored keys.
  17 export async function generateText(input: GenerateTextInput): Promise<GenerateTextOutput> {
  18 
  19 
  20   const promptTemplate = ai.definePrompt({
  21     name: 'generateTextPrompt',
  22     input: { schema: GenerateTextInputSchema },
  23     // No output schema - model returns plain text
  24     model: 'ollama/gemma:2b',
  25     config: {
  26       temperature: RECOMMENDED_TEMPERATURES.CREATIVE,
  27     },
  28     prompt: `You are a writing assistant. Generate text based on the following prompt.
  29 
  30 Output ONLY the generated text. Do NOT wrap it in JSON or any other format.
  31 
  32 **Prompt:** {{{prompt}}}`,
  33   });
  34 
  35   const generateTextFlow = ai.defineFlow(
  36     {
  37       name: 'generateTextFlow',
  38       inputSchema: GenerateTextInputSchema,
  39       outputSchema: GenerateTextOutputSchema,
  40     },
  41     async (flowInput) => {
  42       try {
  43         const result = await promptTemplate(flowInput);
  44         
  45         if (!result) {
  46           throw new Error('No output received from the model.');
  47         }
  48 
  49         // Wrap the plain text in the expected output structure
  50         const output: GenerateTextOutput = {
  51           generatedText: result.text || result.output || ''
  52         };
  53 
  54         if (!output.generatedText || output.generatedText.trim().length === 0) {
  55           throw new Error('Model returned empty text');
  56         }
  57 
  58         return output;
  59       } catch (error) {
  60         console.error('Error in generateTextFlow:', error);
  61         throw new Error(`Text generation failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
  62       }
  63     }
  64   );
  65 
  66   return generateTextFlow(input);
  67 }
