    async log(entry: GenerationLog): Promise<void> {
        try {
            const dataToSave = {
                ...entry,
                createdAt: new Date().toISOString(),
            };
            await this.collection.add(dataToSave);
        } catch (error) {
            console.error(`Failed to log generation for agent ${entry.agentId}:`, error);
        }
    }
}

